begin;
-- Assert the target is still the known synthetic demo; preserve accounts and audit history.
do $$ declare sid uuid; t text; begin
 select id into sid from public.societies where name='DEMO SunSync Society — SYNTHETIC DATA' and address='Fictional demonstration address, not a real installation' for update;
 if sid is not null then
 if exists(select 1 from public.readings where society_id=sid and source not like 'DEMO SYNTHETIC%') or exists(select 1 from public.memberships where society_id=sid and unit not like 'DEMO-%') then raise exception 'Non-demo records detected; abort replacement'; end if;
 delete from public.reading_revisions where reading_id in (select id from public.readings where society_id=sid);
 foreach t in array array['credit_transactions','allocations','allocation_batches','readings','devices','memberships','installations','buildings','tariffs','emission_factors','allocation_rules','community_challenges','notifications','subscriptions','registration_requests','role_assignments'] loop execute format('delete from public.%I where society_id=$1',t) using sid; end loop;
 -- Preserve audit contents and original society identity without a dangling FK.
 update public.audit_logs set details=details||jsonb_build_object('archived_society_id',sid,'archived_society_name','DEMO SunSync Society — SYNTHETIC DATA'),society_id=null where society_id=sid;
 delete from public.societies where id=sid;
 end if;
end $$;
delete from public.notifications where title='Society application reviewed' and body like 'Approved: DEMO ONLY:%';
delete from public.plans p where name='DEMO synthetic entitlement' and not exists(select 1 from public.subscriptions s where s.plan_id=p.id);
commit;
